// SYSTEM DESIGN DSA LAYER — DECISION FRAMEWORK

// Every system design question has a DSA layer:
const systemDesignQuestions = [
    {
        question: 'Design a distributed cache for 10M users',
        dsaDecisions: [
            { component: 'Cache storage', ds: 'HashMap', justification: 'O(1) exact-match session lookup; no range query needed' },
