// OFFER NEGOTIATION FRAMEWORK:
const negotiationFramework = {
    step1: 'Always take 24-48 hours before responding to any offer',
    step2: 'Research market rate: levels.fyi, Glassdoor, Blind, LinkedIn Salary',
    step3: 'Calculate total compensation: base + equity (4yr) + bonus + signing',
    step4: 'Counter with a range: "Based on market data, I was expecting $X-Y base"',
    step5: 'Negotiate equity separately: "Is there flexibility on the equity package?"',
    step6: 'Signing bonus is most negotiable: companies often add 50-100% to counter',
    redlines: [
        'Never reveal current salary (use "I prefer to focus on the market rate for this role")',
        'Never accept verbally immediately ("I need 48 hours to review the full offer")',
        'Never lie about competing offers (but do not disclose details either)',
    ]
};

console.log('Negotiation steps:', Object.keys(negotiationFramework).length - 1);
for (const [k,v] of Object.entries(negotiationFramework)) {
    if (k !== 'redlines') console.log(`${k}: ${v}`);
}
